<?php use App\Core\CSRF;$e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); ?>
<div class="sports-head"><div><span class="sports-kicker">COMPETIR</span><h1>Torneios</h1><p>Inscrições, equipes, jogadores, grupos, mata-mata, partidas, placares, classificação e campeão.</p></div></div>
<div class="row g-4"><div class="col-xl-4"><form class="card border-0 shadow-sm" method="post" action="/sports/tournaments"><div class="card-body"><?=CSRF::field()?><h2 class="h5">Nova competição</h2><input class="form-control mb-2" name="name" required placeholder="Copa Arena"><select class="form-select mb-2" name="modality_id"><option value="">Modalidade</option><?php foreach($modalities as $m):?><option value="<?=(int)$m['id']?>"><?=$e($m['name'])?></option><?php endforeach;?></select><input class="form-control mb-2" name="category" placeholder="Categoria"><select class="form-select mb-2" name="format"><option value="groups_knockout">Grupos + mata-mata</option><option value="groups">Grupos</option><option value="knockout">Mata-mata</option></select><input class="form-control mb-2" name="registration_amount" value="0,00" placeholder="Inscrição"><div class="row g-2"><div class="col-6"><input class="form-control" type="date" name="starts_on" required></div><div class="col-6"><input class="form-control" type="date" name="ends_on"></div></div><button class="btn btn-primary w-100 mt-2">Criar torneio</button></div></form></div>
<div class="col-xl-8"><div class="sports-grid"><?php foreach($tournaments as $t):?><article class="sports-court-card"><div class="p-3"><span class="sports-status status-confirmed"><?=$e($t['status'])?></span><h2 class="h5 mt-2"><?=$e($t['name'])?></h2><p><?=$e($t['modality_name']??'')?> · <?=$e($t['category']??'')?></p><div class="arena-mini-kpis"><span><strong><?=(int)$t['teams']?></strong><small>equipes</small></span><span><strong><?=(int)$t['matches']?></strong><small>partidas</small></span><span><strong><?=date('d/m/Y',strtotime($t['starts_on']))?></strong><small>início</small></span></div><?php if($t['champion_name']):?><div class="alert alert-success mt-2 mb-2">🏆 Campeão: <?=$e($t['champion_name'])?></div><?php endif;?><a class="btn btn-sm btn-outline-primary" href="/sports/tournaments/<?=(int)$t['id']?>">Gerenciar competição</a></div></article><?php endforeach;?></div></div></div>
